static int Multiply(int x, int y) {           // no *: add x · 2^k for each 1 of y
    int r = 0;
    for (uint u = (uint)y; u != 0; u >>= 1, x <<= 1)
        if ((u & 1) != 0) r += x;
    return r;                                 // modulo 2^32, like a plain unchecked x * y
}
